script:
$token = (Get-Content "C:\Users\E\AppData\Local\hermes\.env" -Raw | Select-String "OPENAI_API_KEY=(.*)").Matches.Groups[1].Value.Trim()
try {
  $headers = @{ "Authorization" = "Bearer $token"; "Content-Type" = "application/json" }
  $body = @{ model = "space-bunny-free"; messages = @(@{ role = "user"; content = "Say OK" }); max_tokens = 10 } | ConvertTo-Json -Depth 5
  $resp = Invoke-WebRequest -Uri "https://opencode.ai/zen/v1/chat/completions" -Method Post -Headers $headers -Body $body -TimeoutSec 30 -UseBasicParsing
  "Status: $($resp.StatusCode)"
  "Response: " + ($resp.Content | ConvertFrom-Json).choices[0].message.content
} catch {
  "Error: $($_.Exception.Message)"
}
